<?php defined('ABSPATH')||exit;$s=rema_get_settings();if(!empty($s['footer']['show'])):?><footer class="rema-footer"><div class="container"><div class="row g-5"><div class="col-lg-5"><div class="rema-footer-about"><?php echo wp_kses_post(rema_t($s['footer']['about']));?></div><h2><?php echo wp_kses_post(rema_t($s['footer']['follow']));?></h2><div class="rema-socials"><?php foreach($s['footer']['socials'] as $item):?><a href="<?php echo esc_url($item['url']);?>" target="_blank" rel="noopener" aria-label="<?php echo esc_attr($item['label']);?>"><?php echo rema_icon_or_image($item);?></a><?php endforeach;?></div></div><div class="col-6 col-lg-3 rema-footer-links"><h2><?php echo wp_kses_post(rema_t($s['footer']['quick']));?></h2><ul><?php foreach($s['footer']['links'] as $item):?><li><a href="<?php echo esc_url($item['url']);?>"><?php echo esc_html(rema_t($item['label']));?></a></li><?php endforeach;?></ul></div><div class="col-6 col-lg-4 text-lg-end rema-footer-branding"><div class="rema-footer-logos"><span class="rema-rima-logo light"><img src="<?php echo esc_url(get_template_directory_uri().'/assets/images/rima-logo-mark.svg');?>" alt=""><img src="<?php echo esc_url(get_template_directory_uri().'/assets/images/rima-logo-word.svg');?>" alt="Rima"></span><img src="<?php echo esc_url(get_template_directory_uri().'/assets/images/ramroma-logo.png');?>" alt="Ramroma"></div><div class="rema-payments"><?php foreach(array('payment-applepay.png','payment-mada.png','payment-mada-2.png','payment-stc.png','payment-mastercard.png') as $pay):?><img src="<?php echo esc_url(get_template_directory_uri().'/assets/images/'.$pay);?>" alt=""><?php endforeach;?></div><div class="rema-copyright"><?php echo wp_kses_post(rema_t($s['footer']['copyright']));?></div></div></div></div></footer><?php endif;?><?php wp_footer();?></body></html>
